// Function
function processAndInsertDigitData($conn,$digit615)
{
    try {
        $insertData = [];
		$tracker    = []; // Array untuk mencatat kombinasi unik (kode + d5 + nilai)

        // 1. Iterasi setiap baris array
        foreach ($digit615 as$row) {
            // Processing d5: Hilangkan '-' lalu hilangkan '0' di paling akhir
            $d5 = str_replace('-', '',$row[0]);
            $d5 = rtrim($d5, '0');

            // Iterasi pasangan (kode, nilai) dari d6 (index 1) sampai d15 (index 19)
            $digitNum = 6;
            for ($i = 1; $i < count($row); $i += 2) {$kode  = isset($row[$i]) ? trim($row[$i]) : "";
                $nilai = isset($row[$i + 1]) ? trim($row[$i + 1]) : "";

                // Syarat: kode != '00' DAN nilai != ''
                if ($kode !== '00' &&$nilai !== '') {
                    $tableName = "digit" . $digitNum;

                    // Buat identifier unik untuk kombinasi (kode + d5 + nilai) per tabel
                    $uniqueKey =$kode . '|' . $d5 . '\vert{}' .$nilai;

                    // Cek apakah kombinasi ini sudah pernah dimasukkan sebelumnya ke tabel ini
                    if (!isset($tracker[$tableName][$uniqueKey])) {
                        // Tandai kombinasi ini sudah dimasukkan
                        $tracker[$tableName][$uniqueKey] = true;

                        $kodeEscaped  = mysqli_real_escape_string($conn,$kode);
                        $d5Escaped    = mysqli_real_escape_string($conn, $d5);$nilaiEscaped = mysqli_real_escape_string($conn,$nilai);

                        $insertData[$tableName][] = "('$kodeEscaped', '$d5Escaped', '$nilaiEscaped')";
                    }
                }

                $digitNum++;
            }
        }

        // 2. Matikan Foreign Key Check
        mysqli_query($conn, "SET FOREIGN_KEY_CHECKS = 0;");

        // 3. Eksekusi TRUNCATE & Multi-Insert untuk setiap tabel yang memiliki data
        foreach ($insertData as $tableName =>$values) {
            // Truncate tabel terkait
            $truncateQuery = "TRUNCATE TABLE `$tableName`";
            if (!mysqli_query($conn,$truncateQuery)) {
                throw new Exception("Gagal TRUNCATE tabel $tableName: " . mysqli_error($conn));
            }

            // Multi-Insert
            if (!empty($values)) {$insertQuery = "INSERT INTO `$tableName` (kode, d5, nilai) VALUES " . implode(', ', $values);
                
                if (!mysqli_query($conn,$insertQuery)) {
                    throw new Exception("Gagal insert ke $tableName: " . mysqli_error($conn));
                }
                
                echo "<b>Berhasil!</b> Tabel <code>$tableName</code> diisi ulang dengan " . count($values) . " data unik.<br>";
            }
        }

        // Aktifkan kembali Foreign Key Check
        mysqli_query($conn, "SET FOREIGN_KEY_CHECKS = 1;");
        return true;

    } catch (Exception $e) {
        // Memastikan FK Check selalu diaktifkan kembali jika terjadi error
        mysqli_query($conn, "SET FOREIGN_KEY_CHECKS = 1;");
        echo "<b>Error:</b> " . $e->getMessage();
        return false;
    }
}

// Panggil function
processAndInsertDigitData($conn, $digit615);